//! A stand-in for the model geometry the views and the annotation read (ARCH and STRUCTURE own
//! the real thing): a wall's type, thickness, core, location line and centre line, its faces, the
//! heights an element spans, and outlines in plan of what the model builds.

use super::common::*;
use crate::json::Value;
use crate::project::Project;

/// A wall type's entry in `types.wall` (its `thickness`, `layers`).
pub fn wall_type<'a>(pr: &'a Project, e: &Value) -> Option<&'a Value> {
    let name = lib_ref_name(pr, e, "type")?;
    pr.section("types")?.get("wall")?.get(&name)
}

/// A type of a category's entry in `types.<cat>` by the element's `type` GUID.
pub fn type_entry<'a>(pr: &'a Project, cat: &str, e: &Value) -> Option<&'a Value> {
    let name = lib_ref_name(pr, e, "type")?;
    pr.section("types")?.get(cat)?.get(&name)
}

pub fn wall_thickness(pr: &Project, e: &Value) -> f64 {
    wall_type(pr, e).and_then(|t| f_of(t, "thickness")).unwrap_or(200.0)
}

/// The wall's layers, exterior first: (function, thickness).
pub fn wall_layers(pr: &Project, e: &Value) -> Vec<(String, f64)> {
    let Some(t) = wall_type(pr, e) else { return Vec::new() };
    let Some(a) = t.get("layers").and_then(|l| l.as_arr()) else { return Vec::new() };
    a.iter()
        .map(|l| (s_of(l, "function").unwrap_or("").to_string(), f_of(l, "thickness").unwrap_or(0.0)))
        .collect()
}

/// The core's two faces, as distances from the exterior face: the span of its structure layers
/// (the whole wall where it has none).
pub fn wall_core(pr: &Project, e: &Value) -> (f64, f64) {
    let t = wall_thickness(pr, e);
    let layers = wall_layers(pr, e);
    let mut at = 0.0;
    let mut core: Option<(f64, f64)> = None;
    for (f, th) in &layers {
        if f == "structure" {
            core = Some(match core {
                None => (at, at + th),
                Some((a, _)) => (a, at + th),
            });
        }
        at += th;
    }
    core.unwrap_or((0.0, t))
}

/// How far the wall's centre line lies left of its location line (the line its `start` and `end`
/// give), as its `location` says. The exterior face is the left one.
pub fn centre_offset(pr: &Project, e: &Value) -> f64 {
    let t = wall_thickness(pr, e);
    let (a, b) = wall_core(pr, e);
    match s_of(e, "location").unwrap_or("centre") {
        "exterior-finish" => -t / 2.0,
        "interior-finish" => t / 2.0,
        "core-centre" => (a + b) / 2.0 - t / 2.0,
        "exterior-core" => a - t / 2.0,
        "interior-core" => b - t / 2.0,
        _ => 0.0,
    }
}

/// A wall's line in plan: straight from `start` to `end`, or an arc turning `arc` degrees
/// counter-clockwise between them.
#[derive(Clone, Copy, Debug)]
pub struct WallLine {
    pub start: [f64; 2],
    pub end: [f64; 2],
    /// Degrees turned counter-clockwise (0: straight).
    pub arc: f64,
}

impl WallLine {
    pub fn is_arc(&self) -> bool {
        self.arc.abs() > 1e-9
    }
    pub fn length(&self) -> f64 {
        let c = dist(self.start, self.end);
        if !self.is_arc() {
            return c;
        }
        let (_, r) = self.circle().unwrap();
        r * self.arc.abs().to_radians()
    }
    /// The arc's centre and radius.
    pub fn circle(&self) -> Option<([f64; 2], f64)> {
        if !self.is_arc() {
            return None;
        }
        arc_circle(self.start, self.end, self.arc)
    }
    /// The line moved `d` to its left (an arc: concentric, its radius less `d` for a
    /// counter-clockwise one).
    pub fn offset(&self, d: f64) -> WallLine {
        if !self.is_arc() {
            let n = left_normal(self.start, self.end);
            return WallLine { start: add(self.start, mul(n, d)), end: add(self.end, mul(n, d)), arc: 0.0 };
        }
        let (c, _) = self.circle().unwrap();
        // left of a counter-clockwise arc is toward its centre
        let s = if self.arc > 0.0 { -d } else { d };
        let move_out = |p: [f64; 2]| {
            let v = sub(p, c);
            let l = norm(v);
            add(c, mul(v, (l + s) / l))
        };
        WallLine { start: move_out(self.start), end: move_out(self.end), arc: self.arc }
    }
    /// Points along it, `n` segments for an arc.
    pub fn points(&self, n: usize) -> Vec<[f64; 2]> {
        if !self.is_arc() {
            return vec![self.start, self.end];
        }
        let (c, r) = self.circle().unwrap();
        let a0 = (self.start[1] - c[1]).atan2(self.start[0] - c[0]);
        let sweep = self.arc.to_radians();
        (0..=n).map(|i| {
            let a = a0 + sweep * i as f64 / n as f64;
            [c[0] + r * a.cos(), c[1] + r * a.sin()]
        }).collect()
    }
}

/// The centre and radius of the arc from `a` to `b` turning `deg` degrees counter-clockwise.
pub fn arc_circle(a: [f64; 2], b: [f64; 2], deg: f64) -> Option<([f64; 2], f64)> {
    let t = deg.to_radians();
    let c = dist(a, b);
    if c == 0.0 || t == 0.0 {
        return None;
    }
    let r = c / (2.0 * (t / 2.0).sin().abs());
    let m = mid(a, b);
    // distance from the chord's middle to the centre, toward the left of a→b for a turn under 180
    let h = r * (t / 2.0).cos();
    let n = left_normal(a, b);
    let sign = if t > 0.0 { 1.0 } else { -1.0 };
    Some((add(m, mul(n, h * sign)), r))
}

/// The wall's location line, as its `start`, `end` and `arc` give it.
pub fn location_line(e: &Value) -> WallLine {
    WallLine {
        start: pt_of(e, "start").unwrap_or([0.0, 0.0]),
        end: pt_of(e, "end").unwrap_or([0.0, 0.0]),
        arc: f_of(e, "arc").unwrap_or(0.0),
    }
}

/// The wall's centre line (its location line moved as its `location` says).
pub fn centre_line(pr: &Project, e: &Value) -> WallLine {
    location_line(e).offset(centre_offset(pr, e))
}

/// The wall's left (exterior) and right faces, ends as the wall's own (no joins).
pub fn faces(pr: &Project, e: &Value) -> (WallLine, WallLine) {
    let c = centre_line(pr, e);
    let t = wall_thickness(pr, e);
    (c.offset(t / 2.0), c.offset(-t / 2.0))
}

// ---------------------------------------------------------------- heights

pub fn level_elevation(pr: &Project, e: &Value, k: &str) -> Option<f64> {
    let id = ref_id(pr, e, k)?;
    f_of(pr.el(id)?, "elevation")
}

/// The heights a wall (or a column) spans: its base over its level and its top at its top level
/// (with `top_offset`) or `height` over its base.
pub fn base_top(pr: &Project, e: &Value) -> (f64, f64) {
    let lv = level_elevation(pr, e, "level").unwrap_or(0.0);
    let base = lv + f_of(e, "base_offset").unwrap_or(0.0);
    let top = match level_elevation(pr, e, "top_level") {
        Some(t) => t + f_of(e, "top_offset").unwrap_or(0.0),
        None => base + f_of(e, "height").unwrap_or(3000.0),
    };
    (base, top)
}

// ---------------------------------------------------------------- outlines in plan

/// The outline in plan of a built element where the stand-in knows it: a wall's (its faces, no
/// joins), a floor's, ceiling's or roof's boundary, a column's or footing's rectangle or circle.
pub fn outline(pr: &Project, id: u64) -> Option<Vec<[f64; 2]>> {
    let e = pr.el(id)?;
    match cat(e) {
        "wall" => {
            let (l, r) = faces(pr, e);
            let mut pts = l.points(32);
            let mut back = r.points(32);
            back.reverse();
            pts.extend(back);
            Some(pts)
        }
        "floor" | "ceiling" | "roof" | "shaft" => pts_of(e, "boundary"),
        "column" | "structural_column" | "structuralcolumn" | "footing" => {
            let c = pt_of(e, "at")?;
            let cat_key = match cat(e) {
                "structuralcolumn" => "structural_column",
                x => x,
            };
            let t = type_entry(pr, cat_key, e);
            let w = t.and_then(|t| f_of(t, "width")).unwrap_or(400.0);
            let d = t.and_then(|t| f_of(t, "depth")).unwrap_or(w);
            let round = t.and_then(|t| t.get("round")).and_then(|r| r.as_bool()).unwrap_or(false);
            let a = f_of(e, "angle").unwrap_or(0.0).to_radians();
            if round {
                return Some((0..32).map(|i| {
                    let t = i as f64 / 32.0 * std::f64::consts::TAU;
                    [c[0] + w / 2.0 * t.cos(), c[1] + w / 2.0 * t.sin()]
                }).collect());
            }
            let (ca, sa) = (a.cos(), a.sin());
            Some([[-w / 2.0, -d / 2.0], [w / 2.0, -d / 2.0], [w / 2.0, d / 2.0], [-w / 2.0, d / 2.0]]
                .iter()
                .map(|p| [c[0] + p[0] * ca - p[1] * sa, c[1] + p[0] * sa + p[1] * ca])
                .collect())
        }
        _ => None,
    }
}

/// The south-west and north-east corners round some points.
pub fn bounds(pts: &[[f64; 2]]) -> Option<([f64; 2], [f64; 2])> {
    let mut it = pts.iter();
    let f = *it.next()?;
    let (mut lo, mut hi) = (f, f);
    for p in it {
        lo = [lo[0].min(p[0]), lo[1].min(p[1])];
        hi = [hi[0].max(p[0]), hi[1].max(p[1])];
    }
    Some((lo, hi))
}

// ---------------------------------------------------------------- vectors

pub fn add(a: [f64; 2], b: [f64; 2]) -> [f64; 2] {
    [a[0] + b[0], a[1] + b[1]]
}
pub fn sub(a: [f64; 2], b: [f64; 2]) -> [f64; 2] {
    [a[0] - b[0], a[1] - b[1]]
}
pub fn mul(a: [f64; 2], k: f64) -> [f64; 2] {
    [a[0] * k, a[1] * k]
}
pub fn dot(a: [f64; 2], b: [f64; 2]) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
pub fn cross(a: [f64; 2], b: [f64; 2]) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
pub fn norm(a: [f64; 2]) -> f64 {
    (a[0] * a[0] + a[1] * a[1]).sqrt()
}
pub fn dist(a: [f64; 2], b: [f64; 2]) -> f64 {
    norm(sub(a, b))
}
pub fn mid(a: [f64; 2], b: [f64; 2]) -> [f64; 2] {
    [(a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0]
}
pub fn unit(a: [f64; 2]) -> [f64; 2] {
    let l = norm(a);
    if l == 0.0 {
        [0.0, 0.0]
    } else {
        [a[0] / l, a[1] / l]
    }
}
/// The unit normal to the left of the way from `a` to `b`.
pub fn left_normal(a: [f64; 2], b: [f64; 2]) -> [f64; 2] {
    let d = unit(sub(b, a));
    [-d[1], d[0]]
}

//! What the view and annotation commands share: views found by name or id, element fields read
//! with defaults, GUID references, rounding to the micron, and the default 3D view.

use crate::json::{Map, Value};
use crate::project::Project;

pub type R<T> = Result<T, String>;

pub use crate::commands::params::{get, given, has, id_of, mm_of, num_of, point3_of, point_of, points_of};

// ---------------------------------------------------------------- numbers

/// A length rounded to the micron, as the original keeps the points it works out.
pub fn r3(x: f64) -> f64 {
    let y = (x * 1000.0).round() / 1000.0;
    if y == 0.0 {
        0.0
    } else {
        y
    }
}

/// A point rounded to the micron.
pub fn r3p(p: [f64; 2]) -> [f64; 2] {
    [r3(p[0]), r3(p[1])]
}

/// A float as Rust's Display shows it in the original's messages (1.5, 17, 1000000000).
pub fn disp(x: f64) -> String {
    format!("{}", x)
}

// ---------------------------------------------------------------- element fields

pub fn cat(e: &Value) -> &str {
    e.get("category").and_then(|c| c.as_str()).unwrap_or("")
}

/// The category of an element by id ("" if there is none).
pub fn cat_of(pr: &Project, id: u64) -> String {
    pr.el(id).map(|e| cat(e).to_string()).unwrap_or_default()
}

/// "wall 100002", as the original's messages name an element.
pub fn cat_id(pr: &Project, id: u64) -> String {
    format!("{} {}", cat_of(pr, id), id)
}

pub fn s_of<'a>(e: &'a Value, k: &str) -> Option<&'a str> {
    e.get(k).and_then(|x| x.as_str())
}

pub fn f_of(e: &Value, k: &str) -> Option<f64> {
    e.get(k).and_then(|x| x.as_f64())
}

pub fn pt_of(e: &Value, k: &str) -> Option<[f64; 2]> {
    let a = e.get(k)?.as_arr()?;
    if a.len() < 2 {
        return None;
    }
    Some([a[0].as_f64()?, a[1].as_f64()?])
}

pub fn pt3_of(e: &Value, k: &str) -> Option<[f64; 3]> {
    let a = e.get(k)?.as_arr()?;
    if a.len() < 3 {
        return None;
    }
    Some([a[0].as_f64()?, a[1].as_f64()?, a[2].as_f64()?])
}

pub fn pts_of(e: &Value, k: &str) -> Option<Vec<[f64; 2]>> {
    let a = e.get(k)?.as_arr()?;
    a.iter()
        .map(|p| {
            let q = p.as_arr()?;
            if q.len() < 2 {
                return None;
            }
            Some([q[0].as_f64()?, q[1].as_f64()?])
        })
        .collect()
}

pub fn pt_value(p: [f64; 2]) -> Value {
    Value::from(p)
}

pub fn pts_value(ps: &[[f64; 2]]) -> Value {
    Value::Arr(ps.iter().map(|p| Value::from(*p)).collect())
}

/// The element's name ("" without one).
pub fn name_of(pr: &Project, id: u64) -> String {
    pr.el(id).and_then(|e| s_of(e, "name")).unwrap_or("").to_string()
}

// ---------------------------------------------------------------- references by GUID

/// The id of the element a GUID field names.
pub fn ref_id(pr: &Project, e: &Value, k: &str) -> Option<u64> {
    let g = s_of(e, k)?;
    pr.find_guid(g)
}

pub fn guid(pr: &Project, id: u64) -> String {
    pr.guid_of(id).unwrap_or_default()
}

/// The library entry name a GUID field of an element names.
pub fn lib_ref_name(pr: &Project, e: &Value, k: &str) -> Option<String> {
    let g = s_of(e, k)?;
    pr.lib_name(g)
}

// ---------------------------------------------------------------- views

/// The categories that are views of the model or of paper.
pub const VIEW_CATEGORIES: &[&str] = &["level", "planview", "section", "elevation", "view3d", "sheet", "schedule"];

pub fn is_view_category(c: &str) -> bool {
    VIEW_CATEGORIES.contains(&c)
}

/// A plan: a level's own plan (the level) or a plan view of it.
pub fn is_plan(pr: &Project, id: u64) -> bool {
    matches!(cat_of(pr, id).as_str(), "level" | "planview")
}

/// The level a plan shows (a level is its own plan).
pub fn plan_level(pr: &Project, id: u64) -> Option<u64> {
    crate::model::level_of_view(pr, id)
}

/// A view's name as messages give it: a sheet by its number.
pub fn view_name(pr: &Project, id: u64) -> String {
    match pr.el(id) {
        Some(e) if cat(e) == "sheet" => s_of(e, "number").unwrap_or("").to_string(),
        Some(e) => s_of(e, "name").unwrap_or("").to_string(),
        None => String::new(),
    }
}

/// A view given by id (any element: what it isn't is the command's to say) or by name: a level's,
/// a plan view's, a section's, an elevation's, a 3D view's or a schedule's name, or a sheet's
/// number. "`view`: X is not a view" for an id the project hasn't (or what is neither a number
/// nor text), "no view named `X`" for a name none has.
pub fn find_view(pr: &Project, cmd: &str, key: &str, v: &Value) -> R<u64> {
    let not = || format!("{}: `{}`: {} is not a view", cmd, key, v.to_compact());
    match v {
        Value::Num(_) => {
            let id = id_of(v).ok_or_else(not)?;
            if pr.elements.contains_key(&id) {
                Ok(id)
            } else {
                Err(not())
            }
        }
        Value::Str(s) => {
            if let Some(id) = find_view_named(pr, s) {
                return Ok(id);
            }
            if let Ok(id) = s.trim().parse::<u64>() {
                if pr.elements.contains_key(&id) {
                    return Ok(id);
                }
            }
            if let Some(g) = crate::model::normalize_guid(s) {
                if let Some(id) = pr.find_guid(&g) {
                    return Ok(id);
                }
            }
            Err(format!("{}: no view named `{}`", cmd, s))
        }
        _ => Err(not()),
    }
}

/// The view of this name (a sheet by its number), the first by id.
pub fn find_view_named(pr: &Project, name: &str) -> Option<u64> {
    for (id, e) in &pr.elements {
        let c = cat(e);
        if c == "sheet" {
            if s_of(e, "number") == Some(name) {
                return Some(*id);
            }
        } else if is_view_category(c) && s_of(e, "name") == Some(name) {
            return Some(*id);
        }
    }
    None
}

/// The `view` parameter (or `key`), if given (null is not given).
pub fn view_param(pr: &Project, cmd: &str, p: &Value, key: &str) -> R<Option<u64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => find_view(pr, cmd, key, v).map(Some),
    }
}

/// The lowest level, the plan commands draw in without a view.
pub fn default_plan(pr: &Project) -> Option<u64> {
    crate::model::default_level(pr)
}

/// The name the default 3D view goes by.
pub const DEFAULT_3D: &str = "{3D}";

/// Whether a view name is the default 3D view's (in any case).
pub fn is_default_3d_name(s: &str) -> bool {
    s.to_lowercase() == "{3d}"
}

/// The default 3D view, if it has come to be.
pub fn default_3d(pr: &Project) -> Option<u64> {
    pr.elements
        .iter()
        .find(|(_, e)| cat(e) == "view3d" && s_of(e, "name") == Some(DEFAULT_3D) && e.get("camera").is_none())
        .map(|(id, _)| *id)
        .or_else(|| {
            pr.elements
                .iter()
                .find(|(_, e)| cat(e) == "view3d" && s_of(e, "name") == Some(DEFAULT_3D))
                .map(|(id, _)| *id)
        })
}

/// The default 3D view, made as the original makes it when it is first changed or placed.
pub fn ensure_default_3d(pr: &mut Project) -> u64 {
    if let Some(id) = default_3d(pr) {
        return id;
    }
    let id = pr.alloc_id();
    pr.elements.insert(
        id,
        jobj! {
            "guid" => crate::rand::guid(),
            "category" => "view3d",
            "name" => DEFAULT_3D,
            "azimuth" => -45.0,
            "elevation" => 30.0,
        },
    );
    id
}

/// Every element of a category, by id.
pub fn ids_of(pr: &Project, c: &str) -> Vec<u64> {
    pr.ids_of(c)
}

/// An element's field as an object, made empty where it isn't one (`graphics`, `crop`…).
pub fn obj_field<'a>(e: &'a mut Value, k: &str) -> &'a mut Map {
    if !matches!(e.get(k), Some(Value::Obj(_))) {
        e.set(k, Value::obj());
    }
    e.get_mut(k).unwrap().as_obj_mut().unwrap()
}

// ---------------------------------------------------------------- languages

/// The project's language code (en by default).
pub fn lang(pr: &Project) -> String {
    pr.language()
}

/// A word of the project's language from a table of (en, pt, es, sv, cs, fr, nl, de, it).
pub fn word(pr: &Project, t: [&'static str; 9]) -> &'static str {
    let i = crate::project::LANGS.iter().position(|l| *l == pr.language()).unwrap_or(0);
    t[i]
}
