#!/usr/bin/env python3
"""show.py [-m] [-b] [-f in.bimcraft] [-s setup]... [-a] cmds.txt
Each line: commands separated by ' ;; ' run in one fresh run; prints the last reply (or all with -a)
and the elements saved that weren't in the input (or a new project), and changed library entries.
-b: run both and print only differences (SAME/DIFF)."""
import json, os, subprocess, sys, tempfile, shutil, re
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-a3aa4b1d689cb6d8a/target/release/bimcraft-cli')
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
a = sys.argv[1:]
exes = [ORIG]; infile = None; setup = []; allout = False; both = False; full = False
while a:
    if a[0] == '-m': exes = [MINE]; a = a[1:]
    elif a[0] == '-b': exes = [ORIG, MINE]; both = True; a = a[1:]
    elif a[0] == '-f': infile = a[1]; a = a[2:]
    elif a[0] == '-s': setup.append(a[1]); a = a[2:]
    elif a[0] == '-a': allout = True; a = a[1:]
    elif a[0] == '-F': full = True; a = a[1:]
    else: break
src = open(a[0]) if a else sys.stdin
lines = [l.rstrip('\n') for l in src if l.strip() and not l.startswith('#')]
def norm(s, m):
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'G%d' % (len(m) + 1)
        return m[g]
    return G.sub(rep, s)
def one(exe, l):
    d = tempfile.mkdtemp(prefix='s', dir='/tmp/views-lines/scratch')
    args = [exe, 'run']
    base_ids = set()
    if infile:
        shutil.copy(infile, d)
        args.append(os.path.basename(infile))
        base = json.load(open(infile))
        base_ids = set(base['elements'].keys())
        base_els = base['elements']
    else:
        base_els = {}
    for s in setup:
        args += ['--cmd', s]
    for c in l.split(' ;; '):
        args += ['--cmd', c]
    args += ['--save', 'zz_out.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=300)
    out = []
    o = p.stdout.decode('utf-8', 'replace').strip().split('\n')
    o = [x for x in o if x and '"format":"bimcraft"' not in x]
    if not allout:
        o = o[-1:]
    out += ['OUT ' + x for x in o]
    if p.stderr:
        out.append('ERR ' + p.stderr.decode('utf-8', 'replace').strip())
    out.append('[%d]' % p.returncode)
    f = os.path.join(d, 'zz_out.bimcraft')
    if os.path.exists(f):
        dd = json.load(open(f))
        for k, e in dd['elements'].items():
            if k not in base_ids or json.dumps(base_els.get(k)) != json.dumps(e):
                if full or e.get('category') not in ('level',) or k in base_ids:
                    out.append('  %s %s' % (k, json.dumps(e, ensure_ascii=False)))
        for k in base_ids:
            if k not in dd['elements']:
                out.append('  %s deleted' % k)
    shutil.rmtree(d)
    m = {}
    return [norm(x, m) for x in out]
os.makedirs('/tmp/views-lines/scratch', exist_ok=True)
same = 0
for l in lines:
    if both:
        r = [one(e, l) for e in exes]
        if r[0] == r[1]:
            same += 1
            print('SAME', l[:200])
        else:
            print('DIFF', l)
            for x in r[0]: print('  o', x[:3000])
            for x in r[1]: print('  m', x[:3000])
    else:
        print('>>', l)
        for x in one(exes[0], l): print('  ', x[:5000])
if both:
    print('%d/%d same' % (same, len(lines)))

