def default_knots(n, p):
    # clamped uniform: p+1 zeros, interior 1..n-p-1 / (n-p), p+1 ones
    k = [0.0]*(p+1)
    m = n - p - 1
    for i in range(1, m+1):
        k.append(i/(m+1))
    k += [1.0]*(p+1)
    return k
