    if u >= knots[n]:
        return n-1
    lo, hi = p, n
    mid = (lo+hi)//2
    while u < knots[mid] or u >= knots[mid+1]:
        if u < knots[mid]: hi = mid
        else: lo = mid
        mid = (lo+hi)//2
    return mid
