import math, sys
sys.path.insert(0, '/tmp/views-lines')
from bspl import deboor
from fitspl import fit_to_control
want = [0, 2, 7, 9, 11, 13, 15, 17, 19, 22, 24, 26, 29, 32, 34, 37, 39, 45, 47, 50, 52, 55, 63, 66, 69, 72, 74, 77, 79, 87, 91, 95, 99, 104, 109, 113, 141, 146, 151, 155, 159, 163, 167, 171, 179, 182, 185, 188, 195, 197, 200, 202, 205, 207, 213, 215, 218, 220, 226, 228, 230, 236, 242, 244, 250, 256]
ctrl = [[0,0],[1000,500],[2000,0],[3000,500]]
knots = [0,0,0,0,1,1,1,1]
def C(u): return deboor(ctrl, knots, 3, u)
N = 256
S = [C(k/N) for k in range(N+1)]
def un2(v):
    l = math.hypot(*v); k = 1.0/l; return (v[0]*k, v[1]*k)
a, b = C(0.0), C(1e-6); st = un2((b[0]-a[0], b[1]-a[1]))
a, b = C(1.0 - 1e-6), C(1.0); et = un2((b[0]-a[0], b[1]-a[1]))
def fit_eval(P, kn, s):
    return deboor(P, kn, 3, s)
def run(mode, rnd, maxiter=200):
    chosen = [0, N]
    for it in range(maxiter):
        Q = [S[i] for i in chosen]
        if rnd: Q = [[round(x, 3), round(y, 3)] for x, y in Q]
        P, kn = fit_to_control(Q, st, et)
        sp = [0.0]
        for i in range(len(Q)-1): sp.append(sp[-1] + math.hypot(Q[i+1][0]-Q[i][0], Q[i+1][1]-Q[i][1]))
        worst = None
        for j in range(len(chosen)-1):
            i0, i1 = chosen[j], chosen[j+1]
            for k in range(i0+1, i1):
                if mode == 'param':
                    s = sp[j] + (sp[j+1]-sp[j])*(k-i0)/(i1-i0)
                    f = fit_eval(P, kn, s)
                    d = math.hypot(f[0]-S[k][0], f[1]-S[k][1])
                elif mode == 'paramlen':
                    # fraction by the original's chord lengths between samples
                    L = [0.0]
                    for m in range(i0, i1): L.append(L[-1] + math.hypot(S[m+1][0]-S[m][0], S[m+1][1]-S[m][1]))
                    s = sp[j] + (sp[j+1]-sp[j])*L[k-i0]/L[-1]
                    f = fit_eval(P, kn, s)
                    d = math.hypot(f[0]-S[k][0], f[1]-S[k][1])
                if d > 0.05 and (worst is None or d > worst[0]):
                    worst = (d, k)
        if worst is None:
            return chosen
        chosen.append(worst[1]); chosen.sort()
    return chosen
for mode in ['param', 'paramlen']:
    for rnd in [False, True]:
        ch = run(mode, rnd)
        print(mode, rnd, len(ch), ch == want, ch[:20])

