    a[m + 1] = basis_row(&basis, s[0], d0);
    rhs[m + 1] = b0;
    let (d1, b1) = match et {
        None => (2, [0.0, 0.0]),
        Some(t) => (1, unit(t)),
    };
    a[m + 2] = basis_row(&basis, s[m], d1);
    rhs[m + 2] = b1;
    let ctrl = solve(a, rhs);
    (ctrl, knots)
}

/// The values (or derivatives) of every basis function of a B-spline at `u`.
fn basis_row(b: &Bspline, u: f64, deriv: usize) -> Vec<f64> {
    let n = b.control.len();
    (0..n)
        .map(|i| {
            let mut c = vec![[0.0, 0.0]; n];
            c[i] = [1.0, 0.0];
            let mut bb = Bspline { control: c, knots: b.knots.clone(), degree: b.degree };
            for _ in 0..deriv {
                bb = bb.derivative();
            }
            if bb.control.is_empty() {
                0.0
            } else {
                bb.at(u)[0]
            }
        })
        .collect()
}

/// Solves a small linear system for points (Gauss-Jordan with pivoting).
fn solve(mut a: Vec<Vec<f64>>, mut b: Vec<P2>) -> Vec<P2> {
    let n = a.len();
    for c in 0..n {
        let mut piv = c;
        for r in c + 1..n {
            if a[r][c].abs() > a[piv][c].abs() {
                piv = r;
            }
        }
        a.swap(c, piv);
        b.swap(c, piv);
        let d = a[c][c];
        if d == 0.0 {
            continue;
        }
        for r in 0..n {
            if r != c && a[r][c] != 0.0 {
                let f = a[r][c] / d;
                for k in c..n {
                    a[r][k] -= f * a[c][k];
                }
                b[r] = [b[r][0] - f * b[c][0], b[r][1] - f * b[c][1]];
            }
        }
    }
    (0..n).map(|i| [b[i][0] / a[i][i], b[i][1] / a[i][i]]).collect()
}

