/// parameter over [u0, u1]: its ends and their tangents, with the curve's points added where the
/// fit strays most from it until it is near enough everywhere sampled.
pub fn refit(at: &dyn Fn(f64) -> P2, u0: f64, u1: f64, st: Option<P2>, et: Option<P2>, samples: usize) -> Curve {
    let samples = samples.max(16);
    let us: Vec<f64> = (0..=samples).map(|i| u0 + (u1 - u0) * i as f64 / samples as f64).collect();
    let pts: Vec<P2> = us.iter().map(|u| at(*u)).collect();
    let mut chosen: Vec<usize> = vec![0, samples];
    for _ in 0..samples {
        let fit: Vec<P2> = chosen.iter().map(|i| r3p(pts[*i])).collect();
        let fc = Curve::Fitted { fit: fit.clone(), start_tangent: st, end_tangent: et };
        // the worst sample between the chosen points
        let mut worst: Option<(f64, usize)> = None;
        for w in chosen.windows(2) {
            for i in w[0] + 1..w[1] {
                let d = fc.nearest(pts[i]).dist;
                if d > FIT_TOL && worst.map(|x| d > x.0).unwrap_or(true) {
                    worst = Some((d, i));
                }
            }
        }
        match worst {
            None => return fc,
            Some((_, i)) => {
                let pos = chosen.iter().position(|c| *c > i).unwrap();
                chosen.insert(pos, i);
            }
        }
    }
    Curve::Fitted { fit: chosen.iter().map(|i| r3p(pts[*i])).collect(), start_tangent: st, end_tangent: et }
}

