import math, sys
sys.path.insert(0, '/tmp/views-lines')
from bspl3 import deboor_v
ctrl = [[0,0],[1000,500],[2000,0],[3000,500]]; knots = [0,0,0,0,1,1,1,1]
def C(u): return deboor_v(ctrl, knots, 3, u, 'mix')
exec(open('/tmp/views-lines/an35.py').read().split("N = 55")[0].split("data = ")[0].replace("from bspl import deboor", "from bspl import deboor"))
data = [(1, 0.300000000133074), (5, 0.3000000007615564), (10, 0.300000001333642), (20, 0.3000000023813531), (30, 0.30000000377806074), (40, 0.3000000052712288), (50, 0.30000000641540014), (60, 0.3000000083171807), (70, 0.30000000905273955), (80, 0.3000000110141358), (90, 0.30000001174969454), (99, 0.3000000127941866)]
from bspl import deboor
c = deboor(ctrl, knots, 3, 0.3); c2 = deboor(ctrl, knots, 3, 0.3 + 1e-6)
t = (c2[0]-c[0], c2[1]-c[1]); l = math.hypot(*t); nrm = (-t[1]/l, t[0]/l)
pts = [((c[0] + nrm[0]*d, c[1] + nrm[1]*d), want) for d, want in data]
pts.append(((750.0, 300.0), 0.2532491734100334))
N = 55
us = [i/N for i in range(N+1)]
D = [C(u) for u in us]
def chord(A):
    best = None
    for i in range(N):
        a, b = D[i], D[i+1]
        dx, dy = b[0]-a[0], b[1]-a[1]
        L2 = dx*dx+dy*dy
        s = ((A[0]-a[0])*dx + (A[1]-a[1])*dy)/L2
        s = max(0.0, min(1.0, s))
        x, y = a[0]+s*dx, a[1]+s*dy
        d = math.sqrt((A[0]-x)**2 + (A[1]-y)**2)
        if best is None or d < best[0]: best = (d, i, s)
    d, i, s = best
    return us[i] + s*(us[i+1]-us[i]), i
def dd(A, u, sq):
    p = C(u); x, y = p[0]-A[0], p[1]-A[1]
    return x*x+y*y if sq else math.sqrt(x*x+y*y)
G = (math.sqrt(5)-1)/2
def golden(A, a, b, stop, sq, ret, variant):
    if variant == 0:
        c = b - G*(b-a); d = a + G*(b-a)
        fc, fd = dd(A, c, sq), dd(A, d, sq)
        k = 0
        while not stop(a, b, k):
            if fc < fd:
                b, d, fd = d, c, fc
                c = b - G*(b-a); fc = dd(A, c, sq)
            else:
                a, c, fc = c, d, fd
                d = a + G*(b-a); fd = dd(A, d, sq)
            k += 1
        if ret == 'mid': return (a+b)/2
        return c if fc < fd else d
    else:
        k = 0
        while not stop(a, b, k):
            c = b - G*(b-a); d = a + G*(b-a)
            if dd(A, c, sq) < dd(A, d, sq): b = d
            else: a = c
            k += 1
        return (a+b)/2
hits = {}
for bn in ['seg', 'seg3', 'cent', 'seg2']:
    for sq in [False, True]:
        for var in [0, 1]:
            for ret in ['mid', 'best']:
                for st in ['w1e-9', 'w1e-10', 'w1e-8', 'w1e-12', 'k20', 'k25', 'k30', 'k35', 'k40', 'k45', 'k50', 'w1e-9r', 'w1e-7']:
                    if st.startswith('w'):
                        tol = float(st[1:].rstrip('r'))
                        rel = st.endswith('r')
                        stop = (lambda tol, rel: (lambda a, b, k: (b - a) < tol*(abs(a)+abs(b)) if rel else (b - a) < tol))(tol, rel)
                    else:
                        kk = int(st[1:]); stop = (lambda kk: lambda a, b, k: k >= kk)(kk)
                    n = 0
                    for A, want in pts:
