            Curve::Fitted { fit, start_tangent, end_tangent } => Curve::Fitted {
                fit: fit.iter().map(pt).collect(),
                start_tangent: start_tangent.map(|t| dir9(lin(t))),
                end_tangent: end_tangent.map(|t| dir9(lin(t))),
            },
        }
    }

