                        let i = (seg + k) % n;
                        pts.push(points[i]);
                        if k < n {
                            ar.push(arc_of(i));
                        }
                    }
                    ar.push(a_first);
                    pts.push(q);
                    return Some(Cut::Opened(Curve::polyline(pts, ar, false)));
