168	        [self.centre[0] + self.radius * a.cos(), self.centre[1] + self.radius * a.sin()]
169	    }
170	    pub fn length(&self) -> f64 {
171	        self.radius * self.turn.abs()
172	    }
173	    /// How many chords draw it: no further than FLAT from it, in steps of at most ARC_STEP degrees.
174	    pub fn chords(&self) -> usize {
175	        let step = 2.0 * (1.0 - FLAT / self.radius).acos();
176	        let by_flat = (self.turn.abs() / step).ceil();
177	        let by_step = (self.turn.abs().to_degrees() / ARC_STEP).ceil();
178	        let n = by_flat.max(by_step).max(1.0);
179	        if n.is_finite() {
180	            n as usize
181	        } else {
182	            1
183	        }
184	    }
185	}
