187	/// Whether a turn of this many degrees is straight (under a nanoradian).
188	pub fn is_straight(deg: f64) -> bool {
189	    deg.abs() <= 1e-9f64.to_degrees()
190	}
191	
192	/// The arc from `a` to `b` turning `deg` degrees counter-clockwise (None: straight).
193	pub fn arc_geo(a: P2, b: P2, deg: f64) -> Option<ArcGeo> {
194	    if is_straight(deg) {
195	        return None;
196	    }
197	    let t = deg.to_radians();
198	    let c = dist(a, b);
199	    if c == 0.0 {
200	        return None;
201	    }
202	    let r = c / (2.0 * (t / 2.0).sin().abs());
203	    let m = mid(a, b);
204	    let h = r * (t / 2.0).cos();
205	    let n = left_normal(a, b);
206	    let s = if t > 0.0 { 1.0 } else { -1.0 };
207	    let centre = [m[0] + n[0] * h * s, m[1] + n[1] * h * s];
208	    let start = (a[1] - centre[1]).atan2(a[0] - centre[0]);
209	    Some(ArcGeo { centre, radius: r, start, turn: t })
210	}
211	
212	/// The turn of the arc from `s` to `e` through `t`, degrees (0: as good as straight).
213	pub fn arc_through(s: P2, e: P2, t: P2) -> f64 {
214	    if dist_to_segment(t, s, e) <= 1.0 {
215	        return 0.0;
216	    }
217	    let u = sub(s, t);
218	    let v = sub(e, t);
219	    let cr = cross(u, v);
220	    if cr.abs() <= 1e-9 * norm(u) * norm(v) {
221	        return 0.0;
222	    }
223	    let inscribed = cr.abs().atan2(dot(u, v));
224	    let deg = (2.0 * (PI - inscribed)).to_degrees();
225	    if cross(sub(e, s), sub(t, s)) > 0.0 {
226	        -deg
227	    } else {
228	        deg
229	    }
230	}
