619	    /// The runs of points it is drawn with, each point with its parameter.
620	    pub fn pieces(&self) -> Vec<Piece> {
621	        match self {
622	            Curve::Polyline { .. } => {
623	                self.segments().iter().enumerate().map(|(i, s)| Piece { seg: i, pts: s.drawn() }).collect()
624	            }
625	            Curve::Circle { centre, radius } => {
626	                let step = 2.0 * (1.0 - FLAT / radius).acos();
627	                let n = (2.0 * PI / step).ceil().max(360.0 / ARC_STEP).max(1.0);
628	                let n = if n.is_finite() { (n as usize).min(MAX_DRAWN) } else { 72 };
629	                let pts = (0..=n)
630	                    .map(|k| {
631	                        let a = 2.0 * PI * k as f64 / n as f64;
632	                        (k as f64 / n as f64, [centre[0] + radius * a.cos(), centre[1] + radius * a.sin()])
633	                    })
634	                    .collect();
635	                vec![Piece { seg: 0, pts }]
636	            }
637	            Curve::Ellipse { .. } => {
638	                let (t0, sw) = self.ellipse_range();
639	                let n = self.ellipse_chords();
640	                let pts = (0..=n)
641	                    .map(|k| {
642	                        let t = t0 + k as f64 * (sw / n as f64);
643	                        (k as f64 / n as f64, self.ellipse_at_t(t))
644	                    })
645	                    .collect();
646	                vec![Piece { seg: 0, pts }]
647	            }
648	            Curve::Spline { control, knots } => {
649	                let b = Bspline::new(control, knots.as_deref());
650	                vec![Piece { seg: 0, pts: b.drawn() }]
651	            }
652	            Curve::Fitted { .. } => {
653	                let b = self.fitted_bspline();
654	                vec![Piece { seg: 0, pts: b.drawn() }]
655	            }
656	        }
657	    }
