659	    /// The points it is drawn with, in order (a closed curve's first point again at its end).
660	    pub fn points(&self) -> Vec<P2> {
661	        let mut out: Vec<P2> = Vec::new();
662	        for pc in self.pieces() {
663	            for (i, (_, p)) in pc.pts.iter().enumerate() {
664	                if i == 0 && !out.is_empty() {
665	                    continue;
666	                }
667	                out.push(*p);
668	            }
669	        }
670	        out
671	    }
