673	    /// How long it is: a polyline's and a circle's exactly, the others along the points drawn.
674	    pub fn length(&self) -> f64 {
675	        match self {
676	            Curve::Polyline { .. } => self.segments().iter().map(|s| s.length()).sum(),
677	            Curve::Circle { radius, .. } => 2.0 * PI * radius,
678	            _ => {
679	                let p = self.points();
680	                p.windows(2).map(|w| dist(w[0], w[1])).sum()
681	            }
682	        }
683	    }
