685	    /// The south-west and north-east corners round it as drawn.
686	    pub fn bounds(&self) -> Option<(P2, P2)> {
687	        let pts = self.points();
688	        let mut it = pts.iter();
689	        let f = *it.next()?;
690	        let (mut lo, mut hi) = (f, f);
691	        for p in it {
692	            lo = [lo[0].min(p[0]), lo[1].min(p[1])];
693	            hi = [hi[0].max(p[0]), hi[1].max(p[1])];
694	        }
695	        Some((lo, hi))
696	    }
