708	            Curve::Polyline { points, .. } => points[0],
709	            Curve::Circle { centre, radius } => [centre[0] + radius, centre[1]],
710	            Curve::Ellipse { .. } => {
711	                let (t0, _) = self.ellipse_range();
712	                self.ellipse_at_t(t0)
713	            }
