768	
769	    /// An ellipse's parameter range: where it starts and how far it runs, radians.
770	    pub fn ellipse_range(&self) -> (f64, f64) {
771	        match self {
772	            Curve::Ellipse { span: Some([a, b]), .. } => {
773	                let mut d = (b - a).rem_euclid(360.0);
774	                if d == 0.0 {
775	                    d = 360.0;
776	                }
777	                (a.to_radians(), d.to_radians())
778	            }
779	            _ => (0.0, 2.0 * PI),
780	        }
781	    }
782	
783	    /// An ellipse's span in degrees: where it starts and how far it runs.
784	    fn ellipse_span_deg(&self) -> (f64, f64) {
785	        match self {
786	            Curve::Ellipse { span: Some([a, b]), .. } => {
787	                let mut d = (b - a).rem_euclid(360.0);
788	                if d == 0.0 {
789	                    d = 360.0;
790	                }
791	                (*a, d)
792	            }
793	            _ => (0.0, 360.0),
794	        }
795	    }
796	
797	    pub fn ellipse_at_t(&self, t: f64) -> P2 {
798	        match self {
799	            Curve::Ellipse { centre, radii, angle, .. } => {
800	                let (sa, ca) = angle.to_radians().sin_cos();
801	                let x = radii[0] * t.cos();
802	                let y = radii[1] * t.sin();
803	                [centre[0] + x * ca - y * sa, centre[1] + x * sa + y * ca]
804	            }
805	            _ => [0.0, 0.0],
806	        }
807	    }
808	
809	    fn ellipse_d1(&self, t: f64) -> P2 {
810	        match self {
811	            Curve::Ellipse { radii, angle, .. } => {
812	                let (sa, ca) = angle.to_radians().sin_cos();
813	                let x = -radii[0] * t.sin();
814	                let y = radii[1] * t.cos();
815	                [x * ca - y * sa, x * sa + y * ca]
816	            }
817	            _ => [0.0, 0.0],
818	        }
819	    }
820	
821	    fn ellipse_d2(&self, t: f64) -> P2 {
822	        match self {
823	            Curve::Ellipse { radii, angle, .. } => {
824	                let (sa, ca) = angle.to_radians().sin_cos();
825	                let x = -radii[0] * t.cos();
826	                let y = -radii[1] * t.sin();
827	                [x * ca - y * sa, x * sa + y * ca]
828	            }
829	            _ => [0.0, 0.0],
830	        }
831	    }
832	
833	    /// How many chords draw an ellipse.
834	    fn ellipse_chords(&self) -> usize {
835	        let (_, sw) = self.ellipse_range();
836	        let r = match self {
837	            Curve::Ellipse { radii, .. } => radii[0].abs().max(radii[1].abs()),
838	            _ => 1.0,
839	        };
840	        let step = 2.0 * (1.0 - FLAT / r).acos();
841	        let by_flat = (sw / step).ceil();
842	        let by_step = (sw.to_degrees() / ARC_STEP).ceil();
843	        let n = by_flat.max(by_step).max(8.0) * 2.0;
844	        if n.is_finite() {
845	            (n as usize).min(MAX_DRAWN)
846	        } else {
847	            16
848	        }
849	    }
