851	    pub fn fitted_bspline(&self) -> Bspline {
852	        match self {
853	            Curve::Fitted { fit, start_tangent, end_tangent } => {
854	                let (control, knots) = fit_to_control(fit, *start_tangent, *end_tangent);
855	                Bspline { control, knots, degree: 3 }
856	            }
857	            _ => Bspline { control: vec![[0.0, 0.0], [1.0, 0.0]], knots: vec![0.0, 0.0, 1.0, 1.0], degree: 1 },
858	        }
859	    }
