861	    // ------------------------------------------------------------ nearest
862	
863	    /// Where it passes nearest `p`: on the chords it is drawn with, the parameter there as the
864	    /// chord's ends' parameters run; polished on the curve itself where that comes nearer than the
865	    /// chord does (from the outside of a bend).
866	    pub fn nearest(&self, p: P2) -> Near {
867	        let mut best: Option<(f64, usize, f64)> = None;
868	        for pc in self.pieces() {
869	            for w in pc.pts.windows(2) {
870	                let (fa, a) = w[0];
871	                let (fb, b) = w[1];
872	                let d = sub(b, a);
873	                let l2 = d[0] * d[0] + d[1] * d[1];
874	                let s = if l2 > 0.0 { ((p[0] - a[0]) * d[0] + (p[1] - a[1]) * d[1]) / l2 } else { 0.0 };
875	                let s = s.clamp(0.0, 1.0);
876	                let q = [a[0] + s * d[0], a[1] + s * d[1]];
877	                let dd = (p[0] - q[0]).hypot(p[1] - q[1]);
878	                if best.map(|b| dd < b.0).unwrap_or(true) {
879	                    best = Some((dd, pc.seg, fa + s * (fb - fa)));
880	                }
881	            }
882	        }
883	        let (d, seg, f) = best.unwrap_or((f64::INFINITY, 0, 0.0));
884	        let mut near = Near { seg, f, point: self.at(seg, f), dist: d };
885	        if let Some(f2) = self.polish(seg, f, p) {
886	            let q = self.at(seg, f2);
887	            let d2 = dist(p, q);
888	            if d2 < d {
889	                near = Near { seg, f: f2, point: q, dist: d2 };
890	            }
891	        }
892	        near
893	    }
894	
895	    /// The parameter nearest `p` on the curve itself, from one near it.
896	    fn polish(&self, seg: usize, f: f64, p: P2) -> Option<f64> {
897	        match self {
898	            Curve::Polyline { .. } => {
899	                let s = self.segments()[seg];
900	                let g = s.geo()?;
901	                let a = (p[1] - g.centre[1]).atan2(p[0] - g.centre[0]);
902	                // the angle along the arc from its start, the nearer way round
903	                let mut d = a - g.start;
904	                if g.turn > 0.0 {
905	                    d = d.rem_euclid(2.0 * PI);
906	                    if d > g.turn {
907	                        d = if d - g.turn < 2.0 * PI - d { g.turn } else { 0.0 };
908	                    }
909	                } else {
910	                    d = -(-d).rem_euclid(2.0 * PI);
911	                    if d < g.turn {
912	                        d = if g.turn - d < 2.0 * PI + d { g.turn } else { 0.0 };
913	                    }
914	                }
915	                Some((d / g.turn).clamp(0.0, 1.0))
916	            }
917	            Curve::Circle { centre, .. } => {
918	                let a = (p[1] - centre[1]).atan2(p[0] - centre[0]);
919	                Some(a.rem_euclid(2.0 * PI) / (2.0 * PI))
920	            }
921	            Curve::Ellipse { .. } => {
922	                let (t0, sw) = self.ellipse_range();
923	                let mut t = t0 + sw * f;
924	                for _ in 0..30 {
925	                    let c = self.ellipse_at_t(t);
926	                    let d1 = self.ellipse_d1(t);
927	                    let d2 = self.ellipse_d2(t);
928	                    let e = sub(c, p);
929	                    let g = dot(e, d1);
930	                    let h = dot(d1, d1) + dot(e, d2);
931	                    if h <= 0.0 {
932	                        break;
933	                    }
934	                    let nt = t - g / h;
935	                    if nt == t {
936	                        break;
937	                    }
938	                    t = nt;
939	                }
940	                Some(((t - t0) / sw).clamp(0.0, 1.0))
941	            }
942	            Curve::Spline { control, knots } => {
943	                let b = Bspline::new(control, knots.as_deref());
944	                Some(b.polish(f, p))
945	            }
946	            Curve::Fitted { .. } => Some(self.fitted_bspline().polish(f, p)),
947	        }
948	    }
949	
950	    /// The vertex nearest `p`: its index and how far it is (a polyline's corners, a spline's
951	    /// control points or points passed through).
952	    pub fn nearest_vertex(&self, p: P2) -> Option<(usize, f64)> {
953	        let v: &[P2] = match self {
954	            Curve::Polyline { points, .. } => points,
955	            Curve::Spline { control, .. } => control,
956	            Curve::Fitted { fit, .. } => fit,
957	            _ => return None,
958	        };
959	        let mut best: Option<(usize, f64)> = None;
960	        for (i, q) in v.iter().enumerate() {
961	            let d = dist(p, *q);
962	            if best.map(|b| d < b.1).unwrap_or(true) {
963	                best = Some((i, d));
964	            }
965	        }
966	        best
967	    }
