176	        let by_flat = (self.turn.abs() / step).ceil();
177	        let by_step = (self.turn.abs().to_degrees() / ARC_STEP).ceil();
178	        let n = by_flat.max(by_step).max(1.0);
179	        if n.is_finite() {
180	            n as usize
181	        } else {
182	            1
183	        }
184	    }
