import math, sys, json, pickle
sys.path.insert(0, '/tmp/views-lines')
from polbase import chypot, D2R, ulpdiff, nextf
import polpl
from polpl import Poly, G
cases = pickle.load(open('/tmp/views-lines/pol65.pkl', 'rb'))
def split_point(e1):
    if 'end' in e1: return tuple(e1['end'])
    return tuple(e1['points'][-1])
def nearest2(P, p, clampseg, evalmode):
    D = P.drawn('a')
    best = None
    for k in range(len(D) - 1):
        (ia, fa, ua, A), (ib, fb, ub, B) = D[k], D[k+1]
        dx, dy = B[0]-A[0], B[1]-A[1]
        l2 = dx*dx + dy*dy
        s = ((p[0]-A[0])*dx + (p[1]-A[1])*dy)/l2 if l2 > 0 else 0.0
        s = max(0.0, min(1.0, s))
        Q = (A[0] + s*dx, A[1] + s*dy)
        dd = chypot(p[0]-Q[0], p[1]-Q[1])
        if best is None or dd < best[0]:
            best = (dd, ua + s*(ub - ua), ia)
    dch, uc, ia = best
    rng = float(len(P.segs))
    h = rng/len(D)
    if clampseg:
        lo, hi = max(uc - h, float(ia)), min(uc + h, float(ia + 1))
    else:
        lo, hi = max(uc - h, 0.0), min(uc + h, rng)
    def at(u):
        if evalmode == 'seg':
            return P.seg_at(ia, u - ia)
        return P.at_u(u, 'a')
    Df = lambda u: (lambda c: (c[0]-p[0])**2 + (c[1]-p[1])**2)(at(u))
    a, b = lo, hi
    for _ in range(40):
        w = b - a
        c = b - G*w; d = a + G*w
        if Df(c) < Df(d): b = d
        else: a = c
    u = (a + b)/2
    q = at(u)
    if chypot(q[0]-p[0], q[1]-p[1]) < dch: return q
    return P.at_u(uc, 'a')
for clampseg in [False, True]:
    for evalmode in ['global', 'seg']:
        cnt = {'exact': 0, 'ulp': 0, 'big': 0}
        for pts, arcs, i, fr, off, p, e1, e2 in cases:
            P = Poly(pts, arcs)
            q = nearest2(P, p, clampseg, evalmode)
            qo = split_point(e1)
            if q == qo: cnt['exact'] += 1
            elif math.hypot(q[0]-qo[0], q[1]-qo[1]) < 1e-11: cnt['ulp'] += 1
            else: cnt['big'] += 1
        print('clampseg', clampseg, 'eval', evalmode, cnt)

