fn polish(&self, seg: usize, f: f64, p: P2) -> Option<f64> {
    match self {
        Curve::Polyline { .. } => {
            let s = self.segments()[seg];
            let g = s.geo()?;
            let a = (p[1] - g.centre[1]).atan2(p[0] - g.centre[0]);
