                d = d.rem_euclid(2.0 * PI);
                if d > g.turn {
                    d = if d - g.turn < 2.0 * PI - d { g.turn } else { 0.0 };
                }
            } else {
                d = -(-d).rem_euclid(2.0 * PI);
                if d < g.turn {
                    d = if g.turn - d < 2.0 * PI + d { g.turn } else { 0.0 };
                }
