        let s = if d2.control.len() >= 1 && d1.degree >= 1 { d2.at(u) } else { [0.0, 0.0] };
        let e = sub(c, p);
        let g = dot(e, t);
        let h = dot(t, t) + dot(e, s);
        if h <= 0.0 {
            break;
        }
        let nu = (u - g / h).clamp(lo, hi);
        if nu == u {
            break;
        }
        u = nu;
    }
    u
}

