import json, subprocess, tempfile, shutil, os, sys, glob, re
TEST = sorted(glob.glob('/workspace/.claude/worktrees/agent-a3aa4b1d689cb6d8a/target/release/deps/bimcraft_cli-*'), key=os.path.getmtime)
