    env = dict(os.environ, SPLIT_IN=base, SPLIT_ID='100002', SPLIT_AT=at)
    q = subprocess.run([TEST, 'split_probe', '--ignored', '--nocapture'], capture_output=True, env=env)
    out = q.stdout.decode().split('\n')
    m = []; err = None
    for x in out:
        if x.startswith('ERROR '): err = x
        elif x.startswith('EL '):
            k, js = x[3:].split(' ', 1)
            e = json.loads(js)
            if e.get('category') == 'line': m.append('%s %s' % (k, json.dumps(e, separators=(',', ':'))))
    if err: m = [err]
    shutil.rmtree(d)
    mo, mm = {}, {}
    o2 = [norm(x, mo) for x in o]; m2 = [norm(x, mm) for x in m]
    if o2 == m2:
        same += 1
        if verbose: print('SAME', l)
    else:
        print('DIFF', l)
        for x in o2:
            if x not in m2: print('   o', x[:300])
        for x in m2:
            if x not in o2: print('   m', x[:300])
print('%d/%d same' % (same, n))

