/// `refit`, the points passed through kept to a micrometre (`round`) or as they come.
pub fn refit_with(
    at: &dyn Fn(f64) -> P2,
    u0: f64,
    u1: f64,
    st: Option<P2>,
    et: Option<P2>,
    start: &[f64],
    round: bool,
