    # elimination and back substitution, rhs updated as b[r] -= f*b[c] componentwise in the other order
    a = [r[:] for r in a]; b = [x[:] for x in b]; n = len(a)
    for c in range(n):
        d = a[c][c]
        for r in range(c+1, n):
            if a[r][c] != 0.0:
                f = a[r][c]/d
                a[r][c] = 0.0
                for k in range(c+1, n): a[r][k] = a[r][k] - f*a[c][k]
                b[r] = [b[r][0] - f*b[c][0], b[r][1] - f*b[c][1]]
    x = [[0.0, 0.0] for _ in range(n)]
    for i in range(n-1, -1, -1):
        sx, sy = b[i]
        for k in range(n-1, i, -1):
