/// A spline through `pts` (on the curve `at` between u0 and u1) with the curve's points added where
/// it strays most until it keeps within FIT_TOL.
fn refine_through(at: &dyn Fn(f64) -> P2, u0: f64, u1: f64, pts: Vec<P2>, st: Option<P2>, et: Option<P2>) -> Curve {
    let mut fit = pts;
    let samples = 64;
    for _ in 0..256 {
        let fc = Curve::Fitted { fit: fit.clone(), start_tangent: st, end_tangent: et };
        let mut worst: Option<(f64, P2)> = None;
        for i in 1..samples {
            let q = at(u0 + (u1 - u0) * i as f64 / samples as f64);
            let d = fc.nearest(q).dist;
            if d > FIT_TOL && worst.map(|w| d > w.0).unwrap_or(true) {
                worst = Some((d, q));
            }
        }
        match worst {
            None => return fc,
            Some((_, q)) => {
                // in order along the curve
                let qs = fc.nearest(q).f;
                let s = chord_params(&fit);
                let mut i = 1;
                while i < s.len() - 1 && s[i] <= qs {
                    i += 1;
                }
                if fit.contains(&q) {
                    return fc;
                }
                fit.insert(i, q);
            }
        }
    }
    Curve::Fitted { fit, start_tangent: st, end_tangent: et }
}

