            if d > FIT_TOL && worst.map(|w| d > w.0).unwrap_or(true) {
                worst = Some((d, q));
            }
        }
        match worst {
            None => return fc,
            Some((_, q)) => {
                // in order along the curve
                let qs = fc.nearest(q).f;
                let s = chord_params(&fit);
                let mut i = 1;
