import math, sys, json, subprocess, tempfile, shutil, os, pickle, itertools
sys.path.insert(0, '/tmp/views-lines')
from polbase import chypot, D2R, ulpdiff, nextf
from polarc import chords, nearest_chord
def orig(cmds):
    d = tempfile.mkdtemp(prefix='a', dir='/tmp/views-lines/scratch')
    args = ['/workspace/executable', 'run']
    for c in cmds: args += ['--cmd', c]
    args += ['--save', 'o.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True)
    e = json.load(open(os.path.join(d, 'o.bimcraft')))['elements'] if p.returncode == 0 else None
    shutil.rmtree(d)
    return e
def geo_v(a, b, deg, v):
    t = math.radians(deg)
    dx, dy = b[0]-a[0], b[1]-a[1]
    c = math.sqrt(dx*dx + dy*dy) if v['c'] == 0 else chypot(dx, dy)
    if v['r'] == 0: r = c/(2.0*abs(math.sin(t/2.0)))
    elif v['r'] == 1: r = (c/2.0)/abs(math.sin(t/2.0))
    else: r = c*0.5/abs(math.sin(t*0.5))
    if v['m'] == 0: m = ((a[0]+b[0])/2, (a[1]+b[1])/2)
    elif v['m'] == 1: m = (a[0] + dx/2, a[1] + dy/2)
    else: m = ((a[0]+b[0])*0.5, (a[1]+b[1])*0.5)
    if v['h'] == 0: h = r*math.cos(t/2.0)
    elif v['h'] == 1: h = (c/2.0)/math.tan(abs(t)/2.0)
    else: h = math.sqrt(max(r*r - (c/2.0)**2, 0.0))
    s = 1.0 if t > 0 else -1.0
    if v['n'] == 0:
        nrm = (-dy/c, dx/c); cen = (m[0] + nrm[0]*h*s, m[1] + nrm[1]*h*s)
    elif v['n'] == 1:
        nrm = (-dy/c, dx/c); cen = (m[0] + nrm[0]*(h*s), m[1] + nrm[1]*(h*s))
    elif v['n'] == 2:
        k = h*s/c; cen = (m[0] - dy*k, m[1] + dx*k)
    else:
        l = 1.0/c; nrm = (-dy*l, dx*l); cen = (m[0] + nrm[0]*h*s, m[1] + nrm[1]*h*s)
    st = math.atan2(a[1]-cen[1], a[0]-cen[0])
    return cen, r, st, t
ARCS = [((0.0, 0.0), (700.0, 400.0), 50.0), ((123.4, -567.8), (-345.6, 789.1), -70.0), ((1000.0, 1000.0), (2500.0, 300.0), 110.0), ((-200.0, 50.0), (300.0, 650.0), -30.0)]
CACHE = '/tmp/views-lines/pol112.pkl'
base = {'c': 0, 'r': 0, 'm': 0, 'h': 0, 'n': 0}
if os.path.exists(CACHE):
    cases = pickle.load(open(CACHE, 'rb'))
else:
    cases = []
    for a, b, T in ARCS:
        cen, r, st, t = geo_v(a, b, T, base)
        for off in [-0.7, -4.0]:
            for fr in [0.11, 0.23, 0.37, 0.52, 0.61, 0.78, 0.89]:
                ang = st + t*fr
                p = (cen[0] + (r + off*(1 if T > 0 else -1)*(-1 if T > 0 else 1)*-1)*math.cos(ang), 0)
                # inside the bend: toward the centre
                p = (cen[0] + (r - abs(off))*math.cos(ang), cen[1] + (r - abs(off))*math.sin(ang))
                e = orig(['detail_line ' + json.dumps({"start": list(a), "end": list(b), "arc": T}), 'split {"id":100002,"at":[%r,%r]}' % p])
                if not e or '100003' not in e: continue
                cases.append((a, b, T, p, tuple(e['100002']['end']), e['100002']['arc']))
    pickle.dump(cases, open(CACHE, 'wb'))
print(len(cases), 'cases')
keys = {'c': [0, 1], 'r': [0, 1, 2], 'm': [0, 1, 2], 'h': [0, 1, 2], 'n': [0, 1, 2, 3]}
res = []
for vals in itertools.product(*keys.values()):
    v = dict(zip(keys.keys(), vals))
    okq = 0; oka = 0
    for a, b, T, p, q, arc1 in cases:
        cen, r, st, t = geo_v(a, b, T, v)
        n = chords(r, t)
        P = lambda an: (cen[0] + r*math.cos(an), cen[1] + r*math.sin(an))
        pts = [P(st + t*k/n) for k in range(n + 1)]
        dd, k, s = nearest_chord(p, pts)
        fc = k/n + s*((k+1)/n - k/n)
        if P(st + t*fc) == q: okq += 1
        if T*fc == arc1: oka += 1
    res.append((okq + oka, okq, oka, v))
res.sort(key=lambda x: -x[0])
for x in res[:10]: print(x)

