    elif hv == 'h8': h = (c/2.0)*math.cos(t/2.0)/math.sin(t/2.0)
    elif hv == 'h9': h = c/2.0/math.tan(t/2.0)
    elif hv == 'h10': h = c/(2.0*math.tan(t/2.0))
    rv = v['r']
