    elif nv == 2: cen = (m[0] - dy*h/c, m[1] + dx*h/c)
    elif nv == 3: cen = (m[0] - dy/c*h, m[1] + dx/c*h)
    st = math.atan2(a[1]-cen[1], a[0]-cen[0])
    return cen, r, st, t
keys = {'h': ['h1', 'h3', 'h4', 'h5', 'h6', 'h7', 'h8', 'h9', 'h10'], 'r': ['r0', 'r1', 'r2', 'r3', 'r4'], 'm': [0, 1], 'n': [0, 1, 2, 3]}
res = []
for vals in itertools.product(*keys.values()):
