import math, sys, json, io, contextlib, itertools, pickle
sys.path.insert(0, '/tmp/views-lines')
data = pickle.load(open('/tmp/views-lines/pol92.pkl', 'rb'))
# float natural/clamped cubic spline slopes by the Thomas algorithm, several formulations
def slopes_thomas(ts, ys, st, et, form):
    n = len(ts) - 1
    h = [ts[i+1] - ts[i] for i in range(n)]
    a = [0.0]*(n+1); b = [0.0]*(n+1); c = [0.0]*(n+1); d = [0.0]*(n+1)
    if form == 'inv':
        if st is None:
            b[0] = 2.0/h[0]; c[0] = 1.0/h[0]; d[0] = 3.0*(ys[1]-ys[0])/(h[0]*h[0])
        else:
            b[0] = 1.0; d[0] = st
        for i in range(1, n):
            a[i] = 1.0/h[i-1]; b[i] = 2.0*(1.0/h[i-1] + 1.0/h[i]); c[i] = 1.0/h[i]
            d[i] = 3.0*((ys[i]-ys[i-1])/(h[i-1]*h[i-1]) + (ys[i+1]-ys[i])/(h[i]*h[i]))
        if et is None:
            a[n] = 1.0/h[n-1]; b[n] = 2.0/h[n-1]; d[n] = 3.0*(ys[n]-ys[n-1])/(h[n-1]*h[n-1])
        else:
            b[n] = 1.0; d[n] = et
    else:
        # multiplied form: h[i]*m[i-1] + 2(h[i-1]+h[i]) m[i] + h[i-1] m[i+1] = 3(h[i] dy[i-1]/h[i-1] + h[i-1] dy[i]/h[i])
        if st is None:
            b[0] = 2.0; c[0] = 1.0; d[0] = 3.0*(ys[1]-ys[0])/h[0]
        else:
            b[0] = 1.0; d[0] = st
        for i in range(1, n):
            a[i] = h[i]; b[i] = 2.0*(h[i-1] + h[i]); c[i] = h[i-1]
            d[i] = 3.0*(h[i]*(ys[i]-ys[i-1])/h[i-1] + h[i-1]*(ys[i+1]-ys[i])/h[i])
        if et is None:
            a[n] = 1.0; b[n] = 2.0; d[n] = 3.0*(ys[n]-ys[n-1])/h[n-1]
        else:
            b[n] = 1.0; d[n] = et
    # thomas
    cp = [0.0]*(n+1); dp = [0.0]*(n+1)
    cp[0] = c[0]/b[0]; dp[0] = d[0]/b[0]
    for i in range(1, n+1):
        den = b[i] - a[i]*cp[i-1]
        cp[i] = c[i]/den if i < n else 0.0
        dp[i] = (d[i] - a[i]*dp[i-1])/den
    m = [0.0]*(n+1); m[n] = dp[n]
    for i in range(n-1, -1, -1): m[i] = dp[i] - cp[i]*m[i+1]
    return m, h
def herm(P0, P1, m0, m1, t, form):
    t2 = t*t; t3 = t2*t
    if form == 'h1':
        return (2*t3 - 3*t2 + 1)*P0 + (t3 - 2*t2 + t)*m0 + (-2*t3 + 3*t2)*P1 + (t3 - t2)*m1
    if form == 'h2':
        h00 = 1 - 3*t2 + 2*t3; h10 = t - 2*t2 + t3; h01 = 3*t2 - 2*t3; h11 = t3 - t2
        return h00*P0 + h10*m0 + h01*P1 + h11*m1
    if form == 'bez':
        B1 = P0 + m0/3; B2 = P1 - m1/3; u = 1 - t
        return u*u*u*P0 + 3*u*u*t*B1 + 3*u*t*t*B2 + t*t*t*P1
    if form == 'horner':
        c2 = 3*(P1 - P0) - 2*m0 - m1; c3 = 2*(P0 - P1) + m0 + m1
        return P0 + t*(m0 + t*(c2 + t*c3))
tot = {}
for dl, i, e1, e2 in data:
    fit = [list(map(float, p)) for p in dl['fit']]
    ts = [0.0]
    for p, q in zip(fit, fit[1:]):
        ts.append(ts[-1] + math.sqrt((q[0]-p[0])**2 + (q[1]-p[1])**2))
    st = dl.get('start_tangent'); et = dl.get('end_tangent')
    def ut(t):
        l = math.sqrt(t[0]**2 + t[1]**2); k = 1.0/l; return [t[0]*k, t[1]*k]
    stu = ut(st) if st else None; etu = ut(et) if et else None
    nseg = len(fit) - 1
    for sform in ['inv', 'mul']:
        mx, h = slopes_thomas(ts, [p[0] for p in fit], stu[0] if stu else None, etu[0] if etu else None, sform)
        my, _ = slopes_thomas(ts, [p[1] for p in fit], stu[1] if stu else None, etu[1] if etu else None, sform)
        for hf in ['h1', 'h2', 'bez', 'horner']:
            for pm in ['index', 'chord']:
                hits = 0; n_ = 0
                for piece, pts, (ua, ub) in [(1, e1['fit'], (0, i)), (2, e2['fit'], (i, nseg))]:
                    S = set()
                    for k in range(257):
                        if pm == 'index':
                            u = ua + (ub - ua)*k/256
                            seg = min(int(u), nseg - 1); tau = u - seg
                        else:
                            tt = ts[ua] + (ts[ub] - ts[ua])*k/256
                            seg = 0
                            while seg < nseg - 1 and tt > ts[seg+1]: seg += 1
                            tau = (tt - ts[seg])/h[seg]
                        P0 = fit[seg]; P1 = fit[seg+1]
                        m0 = [mx[seg]*h[seg], my[seg]*h[seg]]; m1 = [mx[seg+1]*h[seg], my[seg+1]*h[seg]]
                        S.add((herm(P0[0], P1[0], m0[0], m1[0], tau, hf), herm(P0[1], P1[1], m0[1], m1[1], tau, hf)))
                    hits += sum(1 for q in pts if tuple(q) in S); n_ += len(pts)
                key = (sform, hf, pm)
                tot.setdefault(key, [0, 0]); tot[key][0] += hits; tot[key][1] += n_
for k, v in sorted(tot.items(), key=lambda kv: -kv[1][0])[:12]: print(k, v)
